def preserve_legacy_requests(apps, schema_editor):
    ExchangeRequest = apps.get_model('swaps', 'ExchangeRequest')
    RequestPreference = apps.get_model('swaps', 'RequestPreference')
    database = schema_editor.connection.alias
    active_requesters = set()
    now = django.utils.timezone.now()

    requests = ExchangeRequest.objects.using(database).select_related(
        'requester',
    ).order_by('requester_id', '-created_at', '-pk')
    for exchange_request in requests:
        requester = exchange_request.requester
        was_pending = exchange_request.status == 'PENDING'
        if was_pending and requester.current_room_id and requester.pk not in active_requesters:
            exchange_request.status = 'OPEN'
            active_requesters.add(requester.pk)
        elif exchange_request.status == 'COMPLETED':
            exchange_request.status = 'COMPLETED'
        else:
            exchange_request.status = 'WITHDRAWN'

        exchange_request.from_room_id = requester.current_room_id or exchange_request.target_room_id
        exchange_request.reason = ''
        exchange_request.expires_at = now + timedelta(days=30)
        exchange_request.save(
            using=database,
            update_fields=('status', 'from_room', 'reason', 'expires_at'),
        )
        RequestPreference.objects.using(database).create(
            exchange_request_id=exchange_request.pk,
            room_id=exchange_request.target_room_id,
            priority=1,
        )


def restore_legacy_target_rooms(apps, schema_editor):
    ExchangeRequest = apps.get_model('swaps', 'ExchangeRequest')
    RequestPreference = apps.get_model('swaps', 'RequestPreference')
    database = schema_editor.connection.alias
    for exchange_request in ExchangeRequest.objects.using(database).all():
        preference = RequestPreference.objects.using(database).filter(
            exchange_request_id=exchange_request.pk,
        ).order_by('priority', 'pk').first()
        if preference:
            exchange_request.target_room_id = preference.room_id
            exchange_request.save(using=database, update_fields=('target_room',))


